14	/// Where to [jump](jump_from_click) to.
15	#[derive(Debug, Clone, Eq, PartialEq)]
16	pub enum Jump {
17	    /// Jump to a position in a file.
18	    File(FileId, usize),
19	    /// Jump to an external URL.
20	    Url(Url),
21	    /// Jump to a point on a page.
22	    Position(PagedPosition),
23	}
