84	    impl JumpFromDocument for HtmlDocument {
85	        type Position = HtmlPosition;
86	
87	        fn resolve_position(
88	            &self,
89	            world: &dyn IdeWorld,
90	            position: &Self::Position,
91	        ) -> Option<Jump> {
92	            let mut current_node = self.root_node();
93	            let mut prefix_len = 0;
94	
95	            let indices_count = position.element().count();
96	            for (i, index) in position.element().enumerate() {
97	                let reached_leaf_node = i == indices_count - 1;
98	                match current_node {
99	                    HtmlNode::Element(html_element) => {
100	                        let (child_index, (mut child, _)) = html_element
101	                            .children
102	                            .iter_with_dom_indices()
103	                            .enumerate()
104	                            .find(|&(_, (child, dom_index))| {
105	                                !matches!(child, HtmlNode::Tag(_)) && dom_index == index
106	                            })?;
107	
108	                        // In some scenarios, Typst will emit multiple
109	                        // consecutive text nodes (called text node parts below),
110	                        // the firsts of which may have detached spans. This is
111	                        // for example the case with the default figure
112	                        // captions: the supplement, counter, and separator will
113	                        // be individual spanless text nodes (and only the actual
114	                        // caption body will have a span).
115	                        //
116	                        // Because the HTML document as parsed by an external
117	                        // program will probably contain a single text node for
118	                        // all that, jumping from the caption body will ask for
119	                        // a jump from the 0-th child of the <figcaption>, at a
120	                        // certain offset. Because `nth_child` doesn't take this
121	                        // offset into account, it will then pick the first text
122	                        // node: in the previous example, the spanless
123	                        // supplement.
124	                        //
125	                        // Below, we compensate for that, and make sure the
126	                        // position can be correctly resolved by picking another
127	                        // text node if needed.
128	                        if reached_leaf_node
129	                            && let HtmlNode::Text(_, _) = child
130	                            && let Some(InnerHtmlPosition::Character(offset)) =
131	                                position.details()
132	                        {
133	                            let mut text_char_count = 0;
134	                            let mut text_node_part = child;
135	                            let mut text_node_offset = 0;
136	
137	                            // The requested offset is expressed as a character
138	                            // index (not a byte offset).
139	                            while text_char_count < *offset {
140	                                prefix_len = text_char_count;
141	
142	                                // Get the current text node part
143	                                text_node_part = html_element
144	                                    .children
145	                                    .get(child_index + text_node_offset)?;
146	
147	                                // And measure its length (in characters), to be
148	                                // able to tell if we are far enough to have
149	                                // reached the character to which we want to
150	                                // jump to.
151	                                let text_node_part_len =
152	                                    if let HtmlNode::Text(text, _) = text_node_part {
153	                                        text.chars().count()
154	                                    } else {
155	                                        0
156	                                    };
157	
158	                                // Prepare the iteration to the next text node,
159	                                // that will happen if we have not yet reached
160	                                // the requested character offset.
161	                                text_char_count += text_node_part_len;
162	                                text_node_offset += 1;
163	                            }
164	
165	                            child = text_node_part;
166	                        }
167	
168	                        current_node = child;
169	                    }
170	                    HtmlNode::Tag(_) | HtmlNode::Text(_, _) | HtmlNode::Frame(_) => {
171	                        return None;
172	                    }
173	                }
174	            }
175	
176	            let span = current_node.span();
177	            let id = span.id()?;
178	            let source = world.source(id).ok()?;
179	            let ast_node = source.find(span)?;
180	            let is_text_node = ast_node.kind() == SyntaxKind::Text;
181	
182	            if let (HtmlNode::Frame(frame), Some(InnerHtmlPosition::Frame(point))) =
183	                (current_node, &position.details())
184	            {
185	                return jump_from_click_in_frame(world, self, &frame.inner, *point);
186	            }
187	
188	            let source_range = ast_node.range();
189	            Some(Jump::File(
190	                id,
191	                source_range.start
192	                    + match (is_text_node, &position.details()) {
193	                        (true, Some(InnerHtmlPosition::Character(i))) => {
194	                            let source_text = &source.text()[source_range];
195	                            let slice: String = source_text
196	                                .chars()
197	                                .take(i.saturating_sub(prefix_len))
198	                                .collect();
199	                            slice.len()
200	                        }
201	                        _ => 0,
202	                    },
203	            ))
204	        }
205	    }
206	}
